def img_url(key, w=1200, h=None):
    pid = IMAGES[key][0]
    u = "https://images.unsplash.com/photo-%s?auto=format&fit=crop&w=%d&q=70" % (pid, w)
    if h:
        u += "&h=%d" % h
    return u
